import{_ as e,o as t,c as s,a4 as d}from"./chunks/framework.BBs01uty.js";const h=JSON.parse('{"title":"机制三：工具系统（src/tools/）","description":"","frontmatter":{},"headers":[],"relativePath":"agent-cli/mechanisms/tools.md","filePath":"agent-cli/mechanisms/tools.md"}'),a={name:"agent-cli/mechanisms/tools.md"};function c(n,o,r,i,l,p){return t(),s("div",null,[...o[0]||(o[0]=[d(`<h1 id="机制三-工具系统-src-tools" tabindex="-1">机制三：工具系统（<code>src/tools/</code>） <a class="header-anchor" href="#机制三-工具系统-src-tools" aria-label="Permalink to &quot;机制三：工具系统（\`src/tools/\`）&quot;">​</a></h1><blockquote><p>15 个内置工具 + 执行编排 + 输出规模口径。分四个文件，职责刻意分开。</p></blockquote><h2 id="_1-文件分工" tabindex="-1">1. 文件分工 <a class="header-anchor" href="#_1-文件分工" aria-label="Permalink to &quot;1. 文件分工&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>职责</th></tr></thead><tbody><tr><td><code>tools/index.ts</code>（70 行）</td><td><strong>薄门面</strong>：对外聚合导出，不内联任何 schema/实现</td></tr><tr><td><code>tools/registry.ts</code>（1065 行）</td><td><strong>15 个工具的唯一定义处</strong>：<code>meta</code>（name/description/parameters/<code>mutating</code>/<code>requiresApproval</code>/<code>backgroundable</code>/<code>output</code>）+ <code>impl</code></td></tr><tr><td><code>tools/executor.ts</code>（291 行）</td><td>执行编排：把每条 <code>ToolSpec</code> 包成带生命周期的实现（权限 / Hook / 截断 / 生命周期事件）</td></tr><tr><td><code>tools/truncate.ts</code>（222 行）</td><td><strong>输出规模口径的唯一实现</strong>（行 / 字节 / 双阈值截断）</td></tr><tr><td><code>tools/definitions.baseline.ts</code></td><td>AC-41 基线快照：重构前 <code>toolDefinitions</code> 的真实序列化（脚本生成 + sha256），断言&quot;重构后 definitions 不变&quot;</td></tr></tbody></table><h2 id="_2-15-个工具" tabindex="-1">2. 15 个工具 <a class="header-anchor" href="#_2-15-个工具" aria-label="Permalink to &quot;2. 15 个工具&quot;">​</a></h2><p><code>bash</code>（含 <code>run_in_background</code>）· <code>read</code> · <code>write</code> · <code>edit</code> · <code>list_dir</code> · <code>glob</code> · <code>grep</code> · <code>web_search</code> · <code>view_image</code> · <code>read_memory</code> · <code>append_memory</code> · <code>write_memory</code> · <code>ask_user</code> · <code>bash_output</code> · <code>kill_task</code></p><p>要点：</p><ul><li><strong>路径安全</strong>：文件类工具只允许<strong>项目根内</strong>（<code>config.projectRoot</code> = 启动目录，白名单语义），防路径穿越。</li><li><strong>bash</strong>：前台走 <code>execAsync</code>（超时 <code>bashTimeoutMs = 60s</code>）；<code>run_in_background: true</code> 走 <code>TaskManager</code>（见 <a href="./background-tasks.html"><code>background-tasks.md</code></a>），<strong>非交互模式显式拒绝</strong>（V-8）。</li><li><strong><code>ask_user</code></strong>：LLM 主动向用户提问 → 走<strong>与权限审批相同的交互路径</strong>（AC-27，见 <a href="./interaction.html"><code>interaction.md</code></a>）。</li><li><strong>memory 三件套</strong>：读写 <code>~/.agent-cli/memory/memory.md</code>。</li><li><strong><code>view_image</code></strong>：预检模型能力（<code>models.ts</code>），把本地图片编码进消息（多模态）。</li></ul><h2 id="_3-执行器的-7-步包装-权限与-hook-的唯一挂载点" tabindex="-1">3. 执行器的 7 步包装（权限与 Hook 的唯一挂载点） <a class="header-anchor" href="#_3-执行器的-7-步包装-权限与-hook-的唯一挂载点" aria-label="Permalink to &quot;3. 执行器的 7 步包装（权限与 Hook 的唯一挂载点）&quot;">​</a></h2><p><code>createToolExecutor</code> 把每条 <code>ToolSpec.impl</code> 包成（<code>tools/executor.ts:158-167</code> 注释原文）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. emit tool_pre                     ← AC-40 前事件</span></span>
<span class="line"><span>2. PreToolUse hook                   ← 非 0/超时则直接返回 {error}，不执行 impl（可先拦，避免无谓弹审批）</span></span>
<span class="line"><span>3. 权限 decidePermission             ← deny 直接返回；ask → requestApproval，拒绝也返回（不中断本轮）</span></span>
<span class="line"><span>4. spec.impl(args, ctx)              ← 真正执行（异常兜底为 {error} 形状）</span></span>
<span class="line"><span>5. truncate                          ← 双阈值截断（作用于工具的有效正文）</span></span>
<span class="line"><span>6. PostToolUse hook                  ← 非阻塞，仅告警</span></span>
<span class="line"><span>7. emit tool_post                    ← AC-40 后事件</span></span></code></pre></div><p>三条纪律：</p><ul><li><strong>pre/post 恒 1:1 成对 emit</strong> —— 包括 hook 阻止与权限拒绝的路径（订阅方要能看到&quot;这次调用被拒了&quot;）。</li><li><strong>拒绝也要给出明确、可继续的结果</strong>（AC-32/37）：LLM 据此换策略，本轮不中断。</li><li><strong><code>PostToolUse</code> 只在真正执行之后触发</strong>（被拦住的调用不触发）。</li></ul><h2 id="_4-输出规模口径-lesson-012-全项目唯一实现" tabindex="-1">4. 输出规模口径（lesson 012，全项目唯一实现） <a class="header-anchor" href="#_4-输出规模口径-lesson-012-全项目唯一实现" aria-label="Permalink to &quot;4. 输出规模口径（lesson 012，全项目唯一实现）&quot;">​</a></h2><p><code>tools/truncate.ts</code>：</p><ul><li><strong>行</strong> = <code>countLines()</code>：按 <code>\\r\\n | \\r | \\n</code> 切分后的段数，<strong>末尾行尾不额外算一行</strong>；空文本 0 行。</li><li><strong>字节</strong> = utf8 字节数。</li><li><strong>双阈值截断</strong>（D19/AC-11）：<code>toolOutputMaxLines = 1000</code>、<code>toolOutputMaxBytes = 50KB</code>；<strong>只作用于文本</strong>，<code>ContentPart[]</code> 的 image 部件豁免（V-4）。</li><li><strong>三者同源</strong>：截断判定、截断标注（&quot;省略 N 行&quot;）、工具行&quot;输出 N 行&quot;必须用同一实现 —— 曾因两套计数出过 bug，这是 lesson 012 的教训。</li><li>W-3 细节：JSON 信封要先<strong>抽出有效正文</strong>再截断/计数（否则行阈值恒不触发）；截断后 <code>result.lines</code> 度量的是<strong>实际交付给 LLM 的内容</strong>。</li></ul><h2 id="_5-生命周期事件-ac-40" tabindex="-1">5. 生命周期事件（AC-40） <a class="header-anchor" href="#_5-生命周期事件-ac-40" aria-label="Permalink to &quot;5. 生命周期事件（AC-40）&quot;">​</a></h2><p><code>executor.on(listener)</code> 订阅 <code>tool_pre</code> / <code>tool_post</code>（含 ok / 耗时 / 行数 / 字节）。返回退订函数。 <code>index.ts</code> 用它驱动工具行的开始/完成渲染 —— <strong>这是工具行渲染的唯一数据来源</strong>（AC-2 的根因修复）。</p><h2 id="_6-ac-41-definitions-基线" tabindex="-1">6. AC-41：definitions 基线 <a class="header-anchor" href="#_6-ac-41-definitions-基线" aria-label="Permalink to &quot;6. AC-41：definitions 基线&quot;">​</a></h2><p><code>definitions.baseline.ts</code> 存着<strong>重构前</strong><code>toolDefinitions</code> 的真实序列化（一次性脚本 dump，附 sha256）。 测试断言&quot;现在的 <code>buildDefinitions()</code> 产出与基线一致（B6 起 bash 有一个显式增参除外）&quot;—— 防止改工具描述破坏 <strong>prompt 前缀稳定性</strong>（见 <a href="./../architecture.html"><code>architecture.md</code></a> 不变量 1）。</p><h2 id="_7-测试" tabindex="-1">7. 测试 <a class="header-anchor" href="#_7-测试" aria-label="Permalink to &quot;7. 测试&quot;">​</a></h2><p><code>tools/tools.test.ts</code>（定义基线 / 分类）、<code>tools/executor.test.ts</code>（7 步编排、权限与 hook 挂载顺序、pre/post 成对）、<code>tools/truncate.test.ts</code>（行/字节口径、双阈值、图片豁免）。</p>`,22)])])}const g=e(a,[["render",c]]);export{h as __pageData,g as default};
